B.TE={"Men\xfa":0,Perfil:1,"GANANCIAS DEL D\xcdA":2,"Hola, ":3,"ELIGE MERCADO Y ACTIVO":4,"SIGUE DESLIZANDO...":5,"GENERAR\nSE\xd1AL":6,TEMPORALIDAD:7,Minuto:8,Minutos:9,"GESTI\xd3N\nDE RIESGO":10,"OPERAR CON\nMG":11,CRIPTO:12,"\xcdNDICES":13,MATERIAS:14,ACCIONES:15,"An\xe1lisis detenido":16,VOLVER:17,"AN\xc1LISIS EN PROCESO":18,"AN\xc1LISIS COMPLETADO":19,ANALIZANDO:20,"LA PACIENCIA TAMBI\xc9N\nES UNA ESTRATEGIA":21,Tendencia:22,Volatilidad:23,Liquidez:24,"Confirmaci\xf3n":25,ALCISTA:26,BAJISTA:27,NEUTRAL:28,BAJA:29,MEDIA:30,ALTA:31,"EN CURSO":32,CONFIRMADA:33,"SIN CONFIRMAR":34,"SE\xd1AL GENERADA":35,"SIN SE\xd1AL CONFIRMADA":36,"OPORTUNIDAD DETECTADA":37,"NO HAY CONFIRMACI\xd3N":38,"FOREX OTC":39,ALZA:40,"SIN SE\xd1AL":41,"TIEMPO DE ENTRADA":42,"En la siguiente vela":43,"TIEMPO DE EXPIRACI\xd3N":44,CONFIANZA:45,"NUEVA SE\xd1AL":46,"OPERAR ALZA":47,"OPERAR BAJA":48,"DISCIPLINA + AN\xc1LISIS = RESULTADOS":49,[u.dE]:50,"No hay una se\xf1al para mostrar.":51,"Sin conexi\xf3n. El an\xe1lisis se detuvo.":52,"No hay velas suficientes.":53,"No se pudo completar el an\xe1lisis.":54,minutos:55,Comprar:56,Vender:57,Mercado:58,Limitada:59,Cantidad:60,"Precio l\xedmite":61,"sin cotizaci\xf3n":62,"REVISAR ORDEN":63,[u.W]:64,RESUMEN:65,Compra:66,Venta:67,[u.N]:68,CONFIRMAR:69,"Revisa cantidad y precio.":70,[u.aA]:71,"DISTRIBUCI\xd3N":72,"Sin posiciones":73,[u.b1]:74,HISTORIAL:75,"Sin operaciones.":76,Cancelar:77,"Sin marca":78,"Cantidad ":79,"Precio medio ":80,Invitado:81,"Biometr\xeda al abrir sesi\xf3n":82,[u.gm]:83,"Autenticaci\xf3n multifactor":84,[u.b_]:85,"Avisos locales":86,[u.db]:87,"Fuente de precios conectada":88,"Fuente de precios activa":89,Desconectada:90,"Comisi\xf3n (bps)":91,"Sesi\xf3n actual":92,"Sin sesi\xf3n":93,"Este dispositivo \xb7 caduca a las 12 h":94,Privacidad:95,[u.M]:96,"Documentaci\xf3n legal":97,"Centro de ayuda":98,"Listas de seguimiento":99,"Reiniciar cuenta":100,"Cuenta reiniciada a 10000.00 USD":101,"CERRAR SESI\xd3N":102,"Operaci\xf3n no encontrada":103,[u.gO]:104,Lado:105,Tipo:106,"Cantidad pedida":107,"Cantidad ejecutada":108,Precio:109,Hora:110,"CANCELAR ORDEN":111,Pendiente:112,Parcial:113,Ejecutada:114,Rechazada:115,Cancelada:116,Fallida:117,MERCADOS:118,"Buscar nombre o s\xedmbolo":119,Todos:120,Cripto:121,"\xcdndices":122,Materias:123,Acciones:124,"Variaci\xf3n":125,Volumen:126,Reconectar:127,"Sin resultados":128,"Prueba con otro s\xedmbolo o categor\xeda.":129,"Sin conexi\xf3n":130,"Sin conexi\xf3n. Cotizaciones detenidas.":131,"GESTI\xd3N DE RIESGO":132,[u.cL]:133,"CAPITAL INICIAL":134,"RIESGO POR OPERACI\xd3N":135,"L\xcdMITE DE P\xc9RDIDA DIARIA":136,"OBJETIVO DIARIO":137,"OPERACIONES DIARIAS":138,"P\xc9RDIDAS CONSECUTIVAS":139,"AJUSTA TU GESTI\xd3N A TU CAPITAL":140,"EL SISTEMA CALCULA":141,GUARDAR:142,[u.gf]:143,"DISCIPLINA + ESTRATEGIA = RESULTADOS":144,"Introduce importes v\xe1lidos.":145,"Gesti\xf3n de riesgo guardada.":146,"OPERAR CON MG":147,[u.e4]:148,[u.cW]:149,"Puesta inicial":150,Multiplicador:151,"EJEMPLO DE LA SECUENCIA DE MG":152,[u.n]:153,"GUARDAR PAR\xc1METROS":154,"Par\xe1metros de MG guardados.":155,"Revisa los valores.":156,[u.eh]:157,"Horario de operaci\xf3n":158,"M\xe1ximo de operaciones":159,"Cu\xe1ndo parar":160,Notas:161,[u.y]:162,"CONTROL DE CAPITAL":163,"Sin capital asignado a posiciones.":164,"REINICIAR CUENTA":165,[u.fl]:166,"Cuenta reiniciada.":167,"L\xcdMITES DE LA GESTI\xd3N":168,[u.gW]:169,"CAPITAL EN POSICIONES":170,uds:171,"Actividad del d\xeda":172,Pausado:173,"Se actualiza cada pocos segundos.":174,"En vivo":175,COMENTARIOS:176,"Comentarios de la comunidad QUANTIX.":177,"mensajes nuevos":178,"Mensaje autom\xe1tico":179,"Autom\xe1tico":180,"La interfaz re\xfane las herramientas en un solo lugar.":181,"El panel de an\xe1lisis muestra tendencia, volatilidad y confirmaci\xf3n.":182,"Se puede consultar el plan de trading y el control de capital.":183,"Las se\xf1ales salen de reglas. Si no hay confirmaci\xf3n, no hay entrada.":184,"La paciencia tambi\xe9n es una estrategia.":185,"Define el riesgo antes de mirar una se\xf1al.":186,"Opera solo con capital que puedas permitirte arriesgar.":187,"La martingala aumenta la exposici\xf3n. Rev\xedsala antes de usarla.":188,"Una se\xf1al no es una orden ejecutada.":189,"Si no hay confirmaci\xf3n, no fuerces la entrada.":190,ALERTAS:191,[u.O]:192,[u.eI]:193,"SE\xd1ALES REGISTRADAS":194,"Todav\xeda no generas una se\xf1al.":195,Confirmada:196,"Sin confirmaci\xf3n":197,WATCHLIST:198,[u.ad]:199,"Nueva lista":200,"Vac\xeda. Marca la estrella en Mercados.":201,AYUDA:202,LEGAL:203,[u.d]:204,[u.b]:205,[u.ea]:206,"Comun\xedcate con el administrador":207,"CONTACTO EN EL LOGIN":208,"Link de WhatsApp, Telegram o web":209,"GUARDAR LINK":210,[u.bG]:211,"No se pudo guardar.":212,"El registro est\xe1 cerrado. Solo el administrador puede crear cuentas.":213,[u.B]:214,"Los usuarios se guardan en el servidor. La persona entra desde cualquier tel\xe9fono con el usuario y la clave que le crees aqu\xed.":215,[u.A]:216,[u.aU]:217,[u.gy]:218,"Solo el administrador puede gestionar cuentas.":219,"CREAR USUARIO":220,"CREAR ACCESO":221,"Usuario creado. Ya puede iniciar sesi\xf3n.":222,"Panel de administraci\xf3n":223,"Crear y gestionar accesos de usuarios":224,Administrador:225,"Administraci\xf3n":226,"Contrase\xf1a temporal":227,Desactivar:228,Activar:229,"Nueva clave":230,Eliminar:231,"Eliminar usuario":232,Habilitado:233,Deshabilitado:234,ADMIN:235,"Acceso denegado":236,"No puedes crear otro usuario admin.":237,"No puedes desactivar la cuenta admin.":238,"No puedes eliminar la cuenta admin.":239,[u.Y]:240,"Solo el administrador puede crear cuentas.":241,"Contrase\xf1a actualizada.":242,"No se pudo actualizar.":243,"Nueva clave para ":244,"\xbfEliminar a ":245,"M\xedn. 8 caracteres, letra y n\xfamero":246,Guardar:247,Usuario:248,"Contrase\xf1a":249,"INICIAR SESI\xd3N":250,"\xbfOlvidaste tu contrase\xf1a?":251,"Crear cuenta":252,"La contrase\xf1a se guarda solo como hash en el almacenamiento seguro. El correo no sale del dispositivo en esta versi\xf3n.":253,Correo:254,REGISTRARME:255,"Recuperar contrase\xf1a":256,"PEDIR C\xd3DIGO":257,"Nueva contrase\xf1a":258,RESTABLECER:259,"Verificar correo":260,"C\xf3digo":261,VERIFICAR:262,"Generar otro c\xf3digo":263,[u.k]:264,[u.o]:265,Desbloquear:266,[u.fr]:267,"USAR BIOMETR\xcdA":268,"No se pudo verificar la biometr\xeda.":269,"Se\xf1ales con reglas":270,[u.fG]:271,"Riesgo y capital":272,[u.gc]:273,"Operaciones y cartera":274,[u.u]:275,[u.J]:276,CONTINUAR:277,EMPEZAR:278,"Espa\xf1ol":279,English:280,"Usuario o contrase\xf1a incorrectos.":281,[u.ez]:282,[u.aj]:283,[u.bY]:284,"El correo no es v\xe1lido.":285,"Ese usuario ya existe.":286,[u.cw]:287,"El c\xf3digo no es v\xe1lido.":288,"El c\xf3digo caduc\xf3. Solicita uno nuevo.":289,"El c\xf3digo caduc\xf3.":290,"Usuario no encontrado.":291,"No hay un c\xf3digo de verificaci\xf3n activo.":292,[u.ef]:293,[u.fp]:294,[u.fQ]:295,"Cantidad superior a la posici\xf3n.":296,"Ejecuci\xf3n parcial. El resto sigue pendiente.":297,"Orden ejecutada.":298,"El capital debe ser mayor que cero.":299,[u.x]:300,[u.gR]:301,"El multiplicador debe ser mayor que 1.":302,[u.eU]:303,"La orden no existe.":304,[u.g0]:305,"Falta la clave de idempotencia.":306,"Selecciona un activo.":307,"La cantidad debe ser mayor que cero.":308,"No hay precio de referencia.":309,[u.a]:310,"La comisi\xf3n configurada no es v\xe1lida.":311,"LIBRO DE \xd3RDENES":312,"L\xednea":313,Velas:314,Indicadores:315,"Sin velas para este per\xedodo":316,"No hay un proveedor de mercado configurado.":317,[u.F]:318,[u.G]:319,"Compra y venta":320,"GENERAR SE\xd1AL AUTOM\xc1TICA":321,"Elige un activo al azar dentro de":322,[u.L]:323,Activo:324,Favorito:325,"Quitar de favoritos":326,"A\xf1adir a favoritos":327,Operar:328,"Gr\xe1fico":329,INICIAL:330,"PRIMER MG":331,"SEGUNDO MG":332,"TERCER MG":333,"CUARTO MG":334,"Mi plan":335,Plan:336,min:337}
